import unicodedata
def nfc(x): return unicodedata.normalize('NFC', x)
TOK = re.compile(r'[\u0621-\u0652\u0670\u0671]+')
def book_spelling(w, text):
    """the book's own spelling of w on that line (the print orders shadda and vowel either way): NFC-equal token, else None"""
    if w in text: return w
    for t in TOK.findall(text):
        if nfc(t) == nfc(w): return t
    return None
out, bad, ours = [], [], []
for k, (unit, src, t, prm, words) in enumerate(P):
    lines = src if isinstance(src, list) else [src]
    text = '\n'.join(SRC[n - 1] for n in lines)
    base = {'entry': f'maqsud:l{unit}', 't': t, **prm, 'src': 'Maqṣūd L' + '–L'.join(str(n) for n in lines)}
    if t == 'js': out.append(base); continue
    if t in ('ilal', 'kept'):
        a = book_spelling(prm['asl'], text)
        if a: base['asl'] = a
        else: base['aslBy'] = 'template'; ours.append((unit, prm['asl']))   # the book names the form and the step, not the aṣl: the sound template gives it
    if t == 'kept': out.append(base); continue
    for w in words:
        b = book_spelling(w, text)
        if not b: bad.append((unit, w)); continue
        out.append({**base, 'w': b})
# ids: entry#hN in order
seen = {}
for p in out:
    seen[p['entry']] = seen.get(p['entry'], 0) + 1; p['id'] = p['entry'] + '#h' + str(seen[p['entry']])
json.dump(out, open(os.path.join(ROOT, 'tools', 'ledger', 'maqsud_hand_probes.json'), 'w', encoding='utf8'), ensure_ascii=False, indent=0)
print(len(out), 'probes over', len(seen), 'units; not on their line:', bad, '; aṣl by the template:', ours)
